const username = "qa.auto." + Date.now();

function gerarCPF() {
    const numeros = Array.from(
        { length: 9 },
        () => Math.floor(Math.random() * 10)
    );

    // Evita sequências com todos os dígitos iguais
    if (numeros.every(n => n === numeros[0])) {
        numeros[0] = (numeros[0] + 1) % 10;
    }

    function calcularDigito(base) {
        const pesoInicial = base.length + 1;

        const soma = base.reduce(
            (total, numero, i) =>
                total + numero * (pesoInicial - i),
            0
        );

        const resto = (soma * 10) % 11;
        return resto === 10 ? 0 : resto;
    }

    numeros.push(calcularDigito(numeros));
    numeros.push(calcularDigito(numeros));

    return numeros.join("");
}

